from logger import log_error

# Definim permisiuni explicite pe roluri
ROLE_PERMISSIONS = {
    "admin": {"upload", "scan", "view_stats", "manage_users"},
    "moderator": {"upload", "scan", "view_stats"},
    "user": {"upload", "scan"},
    "guest": set()  # fallback default role
}

# Lista acțiunilor valide - protecție suplimentară
VALID_ACTIONS = {
    "upload", "scan", "view_stats", "manage_users"
}

def has_permission(role: str, action: str) -> bool:
    role = role.lower().strip()
    action = action.lower().strip()

    if action not in VALID_ACTIONS:
        log_error(f"Invalid action attempted: '{action}'", context={"role": role})
        return False

    permissions = ROLE_PERMISSIONS.get(role)
    if permissions is None:
        log_error(f"Unknown role attempted: '{role}'", context={"action": action})
        return False

    allowed = action in permissions
    if not allowed:
        log_error(f"Unauthorized action: role='{role}', action='{action}'")
    return allowed

# Pentru UI/UX sau debug
def list_permissions(role: str) -> set:
    return ROLE_PERMISSIONS.get(role.lower().strip(), set())

import os
from flask import Flask, request, render_template, redirect, url_for
from flask_wtf.csrf import CSRFProtect
from markupsafe import escape
from permissions_dynamic import grant_permission, revoke_permission
from db import get_db_connection
from dotenv import load_dotenv
from audit_log import log_action

load_dotenv()

app = Flask(__name__)
app.secret_key = os.getenv("SECRET_KEY", "fallback_secret")
csrf = CSRFProtect(app)

@app.route("/admin", methods=["GET"])
def admin_panel():
    message = request.args.get("message", "")
    success = request.args.get("success", "") == "True"

    conn = get_db_connection()
    rows = conn.execute("SELECT role, action FROM role_permissions ORDER BY role, action").fetchall()
    permissions = [{"role": row["role"], "action": row["action"]} for row in rows]
    return render_template("admin_permissions.html", permissions=permissions, message=message, success=success, csrf_token=request.cookies.get('csrf_token'))

@app.route("/admin/grant", methods=["POST"])
def admin_grant():
    role = escape(request.form.get("role", "").strip())
    action = escape(request.form.get("action", "").strip())

    if role and action:
        grant_permission(role, action)
        log_action("GRANT", role, action, request.remote_addr)
        message = f"✅ Permisiunea '{action}' a fost acordată rolului '{role}'."
        return redirect(url_for("admin_panel", message=message, success=True))
    else:
        return redirect(url_for("admin_panel", message="❌ Datele trimise nu sunt valide.", success=False))

@app.route("/admin/revoke", methods=["POST"])
def admin_revoke():
    role = escape(request.form.get("role", "").strip())
    action = escape(request.form.get("action", "").strip())

    if role and action:
        revoke_permission(role, action)
        log_action("REVOKE", role, action, request.remote_addr)
        message = f"⚠️ Permisiunea '{action}' a fost revocată pentru rolul '{role}'."
        return redirect(url_for("admin_panel", message=message, success=True))
    else:
        return redirect(url_for("admin_panel", message="❌ Datele trimise nu sunt valide.", success=False))

if __name__ == "__main__":
    app.run(debug=True)

