import React, { useEffect, useState } from "react";
import axios from "axios";

type Scan = {
  filename: string;
  user?: string;
  is_malicious: boolean;
  reason: string;
  timestamp: string;
};

export default function FileScanLog() {
  const [scans, setScans] = useState<Scan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchScans = async () => {
      try {
        const token = localStorage.getItem("jwt_token");
        const res = await axios.get<Scan[]>("/api/scans", {
          headers: {
            Authorization: `Bearer ${token}`
          }
        });
        setScans(res.data);
      } catch (err) {
        console.error("[FileScanLog] Eroare la fetch:", err);
        setError("Eroare la încărcarea scanărilor");
      } finally {
        setLoading(false);
      }
    };

    fetchScans();
  }, []);

  return (
    <div className="p-4 text-white bg-gray-900 min-h-screen">
      <h2 className="text-2xl font-bold mb-4">🔍 File Scan Activity</h2>

      {loading ? (
        <p className="text-blue-400">Se încarcă scanările...</p>
      ) : error ? (
        <p className="text-red-400">{error}</p>
      ) : scans.length === 0 ? (
        <p className="text-gray-500 italic">Nu există scanări recente...</p>
      ) : (
        <table className="w-full border rounded-xl overflow-hidden shadow">
          <thead className="bg-gray-800 text-white">
            <tr>
              <th className="p-3 text-left">Fișier</th>
              <th className="p-3 text-left">Utilizator</th>
              <th className="p-3 text-left">Status</th>
              <th className="p-3 text-left">Motiv</th>
              <th className="p-3 text-left">Timp</th>
            </tr>
          </thead>
          <tbody>
            {scans.map((scan, i) => (
              <tr
                key={i}
                className={`${
                  scan.is_malicious ? "bg-red-900/40" : "bg-green-800/30"
                } border-b border-gray-700`}
              >
                <td className="p-3">{scan.filename}</td>
                <td className="p-3">{scan.user || "N/A"}</td>
                <td className="p-3">
                  <span
                    className={`px-3 py-1 text-xs font-semibold rounded-full ${
                      scan.is_malicious
                        ? "bg-red-600 text-white"
                        : "bg-green-500 text-white"
                    }`}
                  >
                    {scan.is_malicious ? "MALICIOUS" : "SAFE"}
                  </span>
                </td>
                <td className="p-3">{scan.reason}</td>
                <td className="p-3 text-sm">{new Date(scan.timestamp).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

