import os
import json
from datetime import datetime

MEMORY_DIR = "memory"
PROJECT_MEMORY_FILE = os.path.join(
    MEMORY_DIR,
    "project_memory.json"
)


def load_project_memory():
    if not os.path.exists(PROJECT_MEMORY_FILE):
        return []

    try:
        with open(PROJECT_MEMORY_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except:
        return []


def save_project_memory(data):
    os.makedirs(MEMORY_DIR, exist_ok=True)

    with open(PROJECT_MEMORY_FILE, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=4, ensure_ascii=False)


def remember_project(name, description):
    data = load_project_memory()

    data.append({
        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "name": name,
        "description": description
    })

    save_project_memory(data)

    return f"Project remembered: {name}"


def get_project_memory(name):
    data = load_project_memory()

    results = []

    for item in data:
        if name.lower() in item["name"].lower():
            results.append(item)

    if not results:
        return "Project not found in memory."

    output = []

    for item in results[-5:]:
        output.append(
            f"Project: {item['name']}\n"
            f"Timestamp: {item['timestamp']}\n\n"
            f"{item['description']}"
        )

    return "\n\n---\n\n".join(output)


def search_project_memory(keyword):
    data = load_project_memory()

    keyword = keyword.lower()
    results = []

    for item in data:
        text = (
            item["name"] + " " +
            item["description"]
        ).lower()

        if keyword in text:
            results.append(item)

    if not results:
        return "No project memory found."

    output = []

    for item in results[-10:]:
        output.append(
            f"{item['timestamp']} -> "
            f"{item['name']}"
        )

    return "\n".join(output)


def show_remembered_projects():
    data = load_project_memory()

    if not data:
        return "No remembered projects."

    seen = set()
    output = []

    for item in reversed(data):
        name = item["name"]

        if name.lower() not in seen:
            seen.add(name.lower())

            output.append(
                f"{item['timestamp']} -> {name}"
            )

    return "\n".join(output)


def project_memory_stats():
